\label{thm_main2}
Keep using notations of \Cref{thm_main}. Let $G_n$ be the graph on the vertex set $[n]=\{1,2,\ldots,n\}$ corresponding to $I_n$ for each $n$, and let $E(G_r)=\{\{i_1,j_1\},\ldots,\{i_s,j_s\}\}$ where we assume that $1\le i_t<j_t \le r,\ i_1\le i_2\le \cdots\le i_s$ and if $i_t=i_{t+1}$ then $j_t<j_{t+1}$. Denote $q=\max\{1\le t\le s: i_t=i_1\}$. Denote by $\operatorname{indmatch}(G_n)$ the induced matching number of the graph $G_n$. Then the following statements are equivalent:
\begin{enumerate}[\quad \rm (1)]
 \item $\operatorname{reg} I_n=2$ for all $n\gg 0$;
 \item  Either $j_q = \max\{j_1,\ldots,j_s\}$, or it holds that $\min \{j_t-i_t: t=1,\ldots,s\}=1$ and $\operatorname{indmatch}(G_{3r})=1$.
\end{enumerate}

\label{lem_reg_indmatch}
Let $G$ be a graph with at least one edge. The following statements hold.
\begin{enumerate}[\quad \rm (1)]
 \item There is an inequality $\operatorname{reg} I(G)\ge 1+\operatorname{indmatch}(G)$.
 \item \textup{(Fr\"oberg's theorem)} We have $\operatorname{reg} I(G)=2$ if and only if $G$ is a cochordal graph.
\end{enumerate}

\label{thm_no3K2}
Let ${\mathcal I}=(I_n)_{n\ge 1}$ be an $\operatorname{Inc}$-invariant chain of eventually nonzero edge ideals with the stability index $\operatorname{ind} {\mathcal I}=r\ge 1$. Let $G_n$ be the graph corresponding to $I_n$. Then for all $n\ge 3r$, the graph $G_n$ does not contain any induced $3K_2$ subgraph. In other words, we have $\operatorname{indmatch}(G_n)\le 2$ for all $n\ge 3r$. 

Furthermore, $\operatorname{indmatch}(G_n)=\operatorname{indmatch}(G_{n+1})$ for all $n\ge 3r$.

\label{lem_integralpoints}
Let $1\le i< j\le r$ and $n\ge r$ be positive integers. Then for integers $u<v$, the following are equivalent:
\begin{enumerate}[\quad \rm (1)]
 \item $x_ux_v\in \operatorname{Inc}_{r,n}(x_ix_j)$;
 \item $(u,v)\in \Delta((i,j),n-r)$.
\end{enumerate}
In particular, let ${\mathcal I}=(I_n)_{n\ge 1}$ be an $\operatorname{Inc}$-invariant chain of eventually nonzero edge ideals with $r=\operatorname{ind}({\mathcal I})$, and denote $E(G_r)=\{\{i_1,j_1\},\ldots,\{i_s,j_s\}\}$ where $1\le i_p < j_p\le r$ for $p=1,\ldots,s$. Then for each $n\ge 0$,
\[
E(G_{n+r})=\bigcup_{p=1}^s \left\{\{u,v\}: u,v\in {\mathbb Z}, (u,v)^\le \in \Delta((i_p,j_p),n) \right\}.
\]

The second assertion follows from the fact that $I_{n+r}=\langle \operatorname{Inc}_{r,n+r}(I_r) \rangle_{R_{n+r}}$ and the first assertion. Let us prove the latter.

 (1) $\Rightarrow$ (2): Since $x_ux_v\in \operatorname{Inc}_{r,n}(x_ix_j)$, for some $\pi\in \operatorname{Inc}_{r,n}$, we have $u=\pi(i), v=\pi(j)$. Since $\pi$ is increasing, $\pi(r)\le n$, and $1\le i<j\le r$, we have
 \[
0\le \pi(i)-i \le \pi(j)-j \le \pi(r)-r \le n-r.
 \]
 This implies $(u,v)\in \Delta((i,j),n-r)$.

  \begin{center}
 \begin{figure}[ht!]
  \includegraphics[width=32ex]{Triangles.pdf} 
  \caption{An invariant chain with $I_7=(x_2x_7,x_3x_4)$}
  \label{fig_triangles}
 \end{figure} 
 \end{center}

 (2) $\Rightarrow$ (1): Assume that $(u,v)\in \Delta((i,j),n-r)$. Then there is a chain
 \[
0\le u-i\le v-j\le n-r.
 \]
Choose $\pi: {\mathbb N} \to {\mathbb N}$ such that 
$$\pi(t)= \begin{cases}
           t+u-i, &\text{if $t\le j-1$},\\
           t+v-j, &\text{if $t\ge j$}.
       \end{cases}
$$
Then $\pi \in \operatorname{Inc}_{r,n}$, as $\pi(r)=r+v-j\le n$. It is also clear that $\pi(i)=u, \pi(j)=v$, hence $x_ux_v=\pi(x_ix_j)\in \operatorname{Inc}_{r,n}(x_ix_j)$, as desired.

Let ${\mathcal I}$ be an $\operatorname{Inc}$-invariant chain with $I_7=(x_2x_7,x_3x_4)$ and $I_n=\operatorname{Inc}_{7,n}(I_7)$ for $n\ge 7$. Then using \Cref{lem_integralpoints}, we can compute
\begin{align*}
&I_9= \langle \operatorname{Inc}_{7,9}(x_2x_7) \rangle_{R_9}+ \langle \operatorname{Inc}_{7,9}(x_3x_4) \rangle_{R_9}\\
&= (x_2x_7,x_2x_8,x_2x_9,x_3x_8,x_3x_9,x_4x_9)+(x_3x_4,x_3x_5,x_3x_6,x_4x_5,x_4x_6,x_5x_6). 
\end{align*}
See Figure \ref{fig_triangles}. More generally, for each $n>7$, the generators of the ideal $I_n$ correspond to the lattices points in the union of the two triangles $\Delta((2,7),n-7)$ and $\Delta((3,4),n-7)$.

\label{lem_twopoints_corners}
Assume that $A_1=(i_1,j_1), A_2=(i_2,j_2) \in {\mathbb R}_{\ge 1}^2$ are \textup{(}not necessarily distinct\textup{)} points such that $i_p< j_p, i_1\le i_2$. Let $n\ge \max\{2(j_1-i_1+i_2-j_2),1\}$ be an integer. Let $(u_p,v_p)\in \Delta_{p,n}$, $p=1,2$ be two points such that $(u_1,v_2), (u_2,v_1) \notin \bigcup_{p=1}^2\Delta_{p,n}$. Then the following inequalities hold:
\begin{enumerate}[\quad \rm (1)]
 \item $u_1< v_1, u_2<v_2$;
 \item $u_1<i_2$ and $v_2> j_1+n$;
 \item $i_1<i_2$ and $j_1<j_2$, thus $A_1$ and $A_2$ are distinct.
\end{enumerate}

\label{cor_no3K2_explicit}
Let $A_1=(i_1,j_1), A_2=(i_2,j_2), A_3=(i_3,j_3)\in {\mathbb R}_{\ge 1}^2$ be three given points such that $i_p< j_p$. Assume that $i_1\le i_2\le i_3$.

Denote 
\begin{gather*}
 N=\max \{2(j_1-i_1+i_2-j_2),2(j_1-i_1+i_3-j_3),2(j_2-i_2+i_3-j_3),\\
      \qquad j_1+j_2-2i_1,j_1+j_3-2i_1,j_2+j_3-2i_2,1)\}. 
\end{gather*}
Then $N \le M=2\max\{j_1,j_2,j_3\}$. Moreover, for all $n\ge M$ and for every three points $(u_p,v_p)\in \Delta_{p,n}$, $p=1,2,3$, one of the twelve points $(u_i,u_j), (v_i,v_j)$, $(u_s,v_t)$ \textup{(}where $1\le i<j\le 3, 1\le s, t\le 3, s\neq t$\textup{)}, belongs to $\bigcup_{p=1}^3\Delta_{p,n}$.

\label{prop_noCmc}
Let ${\mathcal I}=(I_n)_{n\ge 1}$ be an $\operatorname{Inc}$-invariant chain of eventually nonzero edge ideals with the stability index $\operatorname{ind} {\mathcal I}=r\ge 1$. Let $G_n$ be the graph corresponding to $I_n$. Let $m\ge 5$ be an integer. Then for all $n\ge mr$, the complement graph $G_n^c$ of $G_n$ has no induced cycle $C_m$.

In particular, for all $n\ge 5r$, the complement graph $G_n^c$ of $G_n$ has no induced cycle $C_m$ for any integer $m$ such that $5\le m \le \dfrac{n}{r}$.

It suffices to prove the first assertion.

Assume the contrary, that there exists $n\ge (m-1)r$ such that $G_{n+r}^c$ contained an induced cycle $a_1,a_2,\ldots,a_m,a_1$ where $1\le a_i\le n+r, a_i\neq a_j$ for $i\neq j$. We may assume that $a_1=\min\{a_1,a_2,\ldots,a_m\}$.

Hence $(a_p,a_q)\in G_{n+r}$ for all $1\le p<q\le m$ such that $q-p\ge 2$ and $(p,q)\neq (1,m)$. By the definition of the stability index, for each pair of integers $(p,q)$ such that $1 \le p, q\le m, q-p\ge 2$ and $(p,q)\neq (1,m)$, there exists $(i_{pq},j_{pq})\in G_r$ where $1\le i_{pq} <j_{pq}\le r$ such that $(a_p,a_q)^\le \in \Delta((i_{pq},j_{pq}),n)$. As in the proof of \Cref{lem_inducedanticyc}, we have

\textbf{Claim 1:}  For all $1\le p\le m$, none of the points $(a_p,a_{p+1}), (a_{p+1},a_p)$ belongs to 
$$
\Gamma=\mathop{\bigcup_{1\le p<q\le r}}_{q\ge p+2, (p,q)\neq (1,m)} \Delta_{pq}.
$$

For $2\le p\le m-2$, note that $(a_p,a_{p+1})\notin \Delta_{1(p+1)}$ by Claim 1. Hence the following chain is false
\[
0\le a_p-i_{1(p+1)} \le a_{p+1}-j_{1(p+1)} \le n.
\]
Since $a_p\ge a_1$ and $(a_1,a_{p+1})\in \Delta_{1(p+1)}$, the first inequality is true. The last inequality is also true, so the middle one is false. Equivalently, we get
\begin{equation}
 \label{eq_ineq_ap+1small}
 a_{p+1}-a_p< j_{1(p+1)} -i_{1(p+1)} \quad \text{for $2\le p\le m-2$}.
\end{equation}
For $3\le p\le m-1$, note that $(a_{p+1},a_p) \notin \Delta_{1p}$ by Claim 1. Therefore the following chain is invalid
\[
0\le a_{p+1}-i_{1p} \le a_p-j_{1p}\le n. 
\]
As $a_{p+1}\ge a_1$, the first and last inequalities are valid, hence the middle one is not. Thus
\begin{equation}
\label{eq_ineq_apsmall}
 a_p - a_{p+1} < j_{1p}-i_{1p} \quad \text{for $3\le p\le m-1$}.
\end{equation}
Applying \Cref{lem_twopoints_corners} with the data $(A_{13}, A_{2m}, (a_1,a_3), (a_2,a_m))$ as in the proof of \Cref{lem_inducedanticyc}, we get
\begin{align}
a_1< & i_{2m} \le a_2, \label{eq_ineq_a1_small}\\
a_3 & \le j_{13}+n < a_m. \label{eq_ineq_a3m}
\end{align}

\textsf{Case I:} $a_2\le a_m$. By \Cref{lem_inducedanticyc}, $a_m=\max\{a_1,\ldots,a_m\}$.

\textbf{Case I.1:} $a_2 \le a_{m-1}$. By Claim 1, $(a_1,a_2)\notin \Delta_{1(m-1)}$ hence the following chain is false
\[
0\le a_1-i_{1(m-1)} \le a_2-j_{1(m-1)} \le n.
\]
The first inequality in the chain holds since $(a_1,a_{m-1})\in \Delta_{1(m-1)}$, and the last inequality also holds since $a_2\le a_{m-1}\le n+j_{1(m-1)}$. Hence the middle inequality is false, namely
\begin{equation}
 \label{eq_ineq_a2small}
 a_2-a_1 < j_{1(m-1)}-i_{1(m-1)}.
\end{equation}
Now $(a_{m-1},a_m)\notin \Delta_{2m}$ by Claim 1 so the following chain is false
\[
0\le a_{m-1}-i_{2m} \le a_m-j_{2m} \le n.
\]
Since $(a_2,a_m)\in \Delta_{2m}$ and $a_2 \le a_{m-1}$ by the hypothesis of Case I.1, we see that the first and last inequalities of the last chain are true. Thus the middle one is false, namely
\begin{equation}
 \label{eq_ineq_amsmall}
 a_m-a_{m-1} < j_{2m}-i_{2m}.
\end{equation}
Using \eqref{eq_ineq_a2small}, \eqref{eq_ineq_ap+1small} multiple times, and \eqref{eq_ineq_amsmall}, we get
\begin{align*}
a_m-a_1 &< (j_{1(m-1)}-i_{1(m-1)})+\sum_{p=2}^{m-2} \left( j_{1(p+1)} -i_{1(p+1)}\right)+(j_{2m}-i_{2m})\\
        & < (m-2)\max\{j_{pq}: 1\le p<q\le m, q\ge p+2, (p,q)\neq (1,m)\} \\
        & \le (m-2)r.
\end{align*}
Together with \eqref{eq_ineq_a1_small} and \eqref{eq_ineq_a3m}, we get
\[
n+j_{13}-i_{2m}< a_m-a_1 < (m-2)r,
\]
so $n< (m-2)r+i_{2m} \le (m-1)r$. This contradicts the hypothesis $n\ge (m-1)r$ from above.


\textbf{Case I.2:} $a_2 > a_{m-1}$.

Consider the points $(a_{m-1},a_2)\in \Delta_{2(m-1)}$  and $(a_3,a_m)\in \Delta_{3m}$. Since none of the points $(a_3,a_2)$, $(a_{m-1},a_m)$ belongs to  $\Gamma$, by \Cref{lem_twopoints_corners} and the fact that $a_m=\max\{a_i: 1\le i\le m\}$, we get $i_{2(m-1)}<i_{3m}$, and 
\begin{equation}
 \label{eq_ineq_am-1small}
 a_{m-1} < i_{3m} \le a_3.
\end{equation}

Consider the points $(a_1,a_{m-2})\in \Delta_{1(m-2)}$ and $(a_{m-1},a_2)\in \Delta_{2(m-1)}$. Arguing as above using \Cref{lem_twopoints_corners} and the fact that $a_1\le a_{m-1}$, we get
\begin{equation}
\label{eq_ineq_a2large}
 a_2 > n+j_{1(m-2)}\ge a_{m-2}.
\end{equation}


We have $(a_3,a_2)\notin \Delta_{2(m-1)}$ per Claim 1, so the following chain is invalid
\[
0\le a_3-i_{2(m-1)} \le a_2-j_{2(m-1)}\le n. 
\]
Thanks to \eqref{eq_ineq_am-1small}, $a_3>a_{m-1}\ge i_{2(m-1)}$ and $a_2-j_{2(m-1)}\le n$, the middle inequality is false, namely
\begin{equation}
\label{eq_ineq_a2-a3small}
 a_2- a_3 < j_{2(m-1)}-i_{2(m-1)}.
\end{equation}
Combining \eqref{eq_ineq_am-1small}, \eqref{eq_ineq_a2large}, \eqref{eq_ineq_apsmall}, and \eqref{eq_ineq_a2-a3small}, we obtain
\begin{align*}
n+j_{1(m-2)}-i_{3m} &< a_2-a_{m-1} \\
                    &=(a_2-a_3)+\sum_{p=3}^{m-2}(a_p-a_{p+1})\\
                    &< j_{2(m-1)}-i_{2(m-1)}+\sum_{p=3}^{m-2}(j_{1p}-i_{1p} ) \quad \text{(by \eqref{eq_ineq_a2-a3small} and \eqref{eq_ineq_apsmall})}\\
                    & < (m-3) \max\{j_{pq}: 1\le p<q\le m, q\ge p+2, (p,q)\neq (1,m)\} \\
        & \le (m-3)r.
\end{align*}
Hence $n < (m-3)r+i_{3m} \le (m-2)r,$ a contradiction. This finishes Case I.



\textsf{Case II:} $a_2 > a_m$. Relabel the vertices as follows: $b_1=a_1, b_i=a_{m+2-i}$ for $2\le i\le m$. Then $b_1=\min\{b_1,\ldots,b_m\}$ and $b_2 < b_m$. Arguing as for Case I, we finish Case II and the proof.

\label{notn_setsandindices}
For simplicity, denote $\Delta_t=\Delta((i_t,j_t),n)$ for any $t=1,\ldots,s$.  Set $J=\{1,2,\ldots,s\},\ J_1=\{t\in J\mid j_t-i_t=\min\{j_1-i_1,\ldots,j_s-i_s\}\}$. Denote
\begin{align*}
b=\min\{t\mid j_t=\max\{j_1,\ldots,j_s\}\}, & \quad B=\max\{t\mid j_t=\max\{j_1,\ldots,j_s\}\},\\
h=\min J_1, & \quad H=\max J_1.
\end{align*}

\label{lem_BandJ1}
With \Cref{notn_setsandindices}, we have $j_H\le j_B$. Moreover, the following statements are equivalent:
\begin{enumerate}[\quad \rm (1)]
 \item $B=H$;
 \item $B\in J_1$;
 \item $j_H=j_B$.
\end{enumerate}

\label{constr_Jsets}
Keep using \Cref{notn_setsandindices}. In this construction, \emph{we assume that $i_b\le i_h$}. 

Note that in this case $i_1=i_q < i_b$, since $j_q=\max\{j_t: i_t=i_1\} < \max\{j_t: t=1,\ldots,s\} = j_b$. Hence $q\in J\setminus J_1$. Indeed, if not, then  $j_q-i_q=\min\{j_t-i_t: 1\le t\le s\}$. This implies $q=1$, and  
$
h=\min \{t: j_t-i_t=\min\{j_1-i_1,\ldots,j_s-i_s\}\}=1,
$
and by the assumption, $i_b \le i_h=i_1$, a contradiction. Thus $q\in J\setminus J_1$ and $i_q < i_b\le i_h$. This justifies the first step of \Cref{alg_Jsets}, which is useful for sorting  the triangles $\Delta_p$.
\begin{algorithm}[H]
\caption{Rearrange the positions of the triangles $\Delta_p$ with $i_b\le i_p\le i_h$}
\label{alg_Jsets}
\begin{flushleft}
\textbf{Input}: The set of edges $\{\{i_1,j_1\},\ldots,\{i_s,j_s\}\}$ of $G_r$ given that $i_b\le i_h$. \\
\textbf{Output}: A sequence of sets $J_1,\ldots,J_\beta$ and a sequence of integers $u_1,\ldots,u_\beta \in \{1,\ldots,s\}$.
\end{flushleft}
\begin{algorithmic}
\State{$t:=1$  }	
\State{$u_1:=h (=\min J_1)$  }	
\While{$J_t\neq \emptyset$ and $i_{u_t}\ge i_{b}$}
\State {$J_{t+1}:=\{p \mid j_p-i_p=\min\{j_a-i_a\mid a\in J\setminus \cup_{i=1}^{t} J_i\;\text{and}\; i_a<i_{u_{t}}\}\}$}
\State{$u_{t+1}:=\min  J_{t+1} $}
\State{$t:=t+1$}
\EndWhile
\end{algorithmic}
\end{algorithm}


Apply Algorithm~\ref{alg_Jsets} and assume that $(\beta-1)$ is the number of repeating steps of this algorithm. By what said above, $\beta\ge 2$, as $J_2\neq \emptyset$. The algorithm gives
\[
J_{\beta}=\{p \mid j_p-i_p=\min\{j_a-i_a\mid a\in J\setminus \cup_{t=1}^{\beta-1} J_t\;\text{and}\; i_a<i_{u_{\beta-1}}\}\}, 
\]
and $u_{\beta}= \min J_{\beta}$. Note that $q\in J\setminus \bigcup_{t=1}^{\beta-1} J_t$ since $i_q< i_b$ and $i_t\ge i_b$ for any $t\in J_1 \cup \cdots \cup J_{\beta-1}$. Hence $J_{\beta}\neq \emptyset$, so because the algorithm stops, we get $i_{u_{\beta}} <i_b$.



It follows that  we obtain a sequence $h=u_1,u_2,\ldots,u_{\beta}\in J$ such that 
\begin{align*}
i_{u_{\beta}} &<i_b\le i_{u_{\beta-1}}<\cdots<i_{u_2}<i_{u_1}=i_h,\\
j_{u_{t+1}}-i_{u_{t+1}}&>j_{u_t}-i_{u_t}\ge 2\quad \text{for}\; t=1,\ldots,\beta-1.
\end{align*}

\label{constr_Ksets}
Keep using \Cref{notn_setsandindices}.  The following algorithm is used to rearrange the positions of the triangles $\Delta_p$. 

\begin{algorithm}[H]
	\caption{Rearrange the positions of the triangles $\Delta_p$ with  $j_{H}<j_p\le j_B$}
	\label{alg_Ksets}
    \begin{flushleft}
    \textbf{Input}: The set of edges $\{\{i_1,j_1\},\ldots,\{i_s,j_s\}\}$ of $G_r$. \\
\textbf{Output}: A sequence of sets $J_1=K_1, K_2, \ldots,K_\gamma$ and a sequence of integers $v_1,\ldots,v_\gamma \in \{1,\ldots,s\}$.
  \end{flushleft}
	\begin{algorithmic}
		\State{$K_1:=J_1$  }
		\State{$t:=1$  }	
		\State{$v_1:=H (=\max K_1)$  }
		\While{$K_t\neq \emptyset$ and $j_{v_t} < j_{B}$}
		\State {$K_{t+1}:=\{p \mid j_p-i_p=\min\{j_a-i_a\mid a\in J\setminus \cup_{i=1}^{t} K_i\;\text{and}\; j_a>j_{v_{t}}\}\}$}
		\State{$v_{t+1}:=\max K_{t+1} $}
		\State{$t:=t+1$}
		\EndWhile
	\end{algorithmic}
\end{algorithm}
In the case $j_H=j_B$, note that $H=B$ by \Cref{lem_BandJ1}, and therefore \Cref{alg_Ksets} does nothing. In other words, $K_1=J_1$, $\gamma=1$, and $v_1=H=B$ in this case.

Consider the case $j_H<j_B$. Apply Algorithm~\ref{alg_Ksets} and assume that $(\gamma-1)$ is the number of repeating steps of this algorithm. Thanks to \Cref{lem_BandJ1}, $B\notin K_1=J_1$ and $j_{v_1}=j_H < j_B$. So $K_2\neq \emptyset$ and $\gamma \ge 2$. 

\textbf{Claim 1:} If $B\in K_t$ for some $2\le t\le \gamma$, then $B=\max K_t=v_t$.

Indeed, since $B\in K_t$, $B\le \max K_t=v_t$. From the setting of \Cref{notn_chainofedgeids}, $i_B\le i_{v_t}$. Since $B\in K_t$, $j_B-i_B=j_{v_t}-i_{v_t}$, so $j_{v_t}-j_B=i_{v_t}-i_B\ge 0$. The definition of $B$ implies $j_{v_t}-j_B\le 0$, so $0=j_{v_t}-j_B=i_{v_t}-i_B$. This forces $B=v_t$.

\textbf{Claim 2:} It holds that $B\in J\setminus \bigcup_{t=1}^{\gamma-1} K_t$. In particular $B\in K_\gamma$ and
\begin{equation}
\label{eq_vgammaB}
v_{\gamma}=B.
\end{equation}

Indeed, we have since that $B\notin K_1$. Assume that $B\in K_t$ for some $2\le t\le \gamma-1$, then $B=v_t$ by Claim 1. But then $j_{v_t}=j_B$, contradicting the description of \Cref{alg_Ksets}. Hence $B\in J\setminus \bigcup_{t=1}^{\gamma-1} K_t$. The description of the algorithm yields $j_{v_{\gamma-1}}<j_B$, so $K_\gamma \neq \emptyset$.  Since the algorithm stops, we deduce $j_{v_\gamma}=j_B$. The definition of $B$ in \Cref{notn_setsandindices} yields $v_\gamma \le B$, so $i_{v_\gamma}\le i_B$. In particular, $j_B-i_B \le j_{v_\gamma}-i_{v_\gamma}$, so the definition of $K_\gamma$, that reads
\[
K_\gamma=\{p \mid j_p-i_p=\min\{j_a-i_a\mid a\in J\setminus \cup_{i=1}^{\gamma-1} K_i\;\text{and}\; j_a>j_{v_{\gamma-1}}\}\}
\]
implies that $B\in K_\gamma$. Using Claim 1, we conclude that $B=\max K_\gamma=v_\gamma$.

So at the end of Algorithm~\ref{alg_Ksets}, we obtain a sequence of indices $H=v_1,v_2,\ldots,v_{\gamma}=B$ such that
\begin{align*}
j_B = j_{v_{\gamma}} &>\cdots>j_{v_2}>j_{v_1}=j_H,\\
j_{v_{t+1}}-i_{v_{t+1}}& >j_{v_t}-i_{v_t}\ge 2\quad \text{for all}\; t=1,\ldots,\gamma-1.
\end{align*}

\label{constr_inducedanticycle}
Keep using \Cref{notn_setsandindices}. Let $h=u_1,u_2,\ldots,u_{\beta}$ be as in \Cref{constr_Jsets} and $H=v_1,v_2,\ldots,v_{\gamma}=B$ be as in \Cref{constr_Ksets} (recalling Equation \eqref{eq_vgammaB}). Now for $n\ge 2r$, we construct an induced anticycle $C_m^c$ in $G_{n+r}$ by considering the following two cases.


\noindent\textbf{Case I: $i_b \le i_h.$}
We employ Algorithm~\ref{alg:anticycle_initialvertices} to construct the initial vertices of $C_m^c$ in $G_{n+r}.$ Note that the numbers $\beta, h=u_1, u_2,\ldots,u_{\beta}$ in \Cref{alg:anticycle_initialvertices} come from the output of \Cref{alg_Jsets}.

\begin{algorithm}[H]
	\caption{Generate the initial vertices of an induced anticycle in $G_{n+r}$}
	\label{alg:anticycle_initialvertices} 
\begin{flushleft}
\textbf{Input}: The set of edges $\{\{i_1,j_1\},\ldots,\{i_s,j_s\}\}$ of $G_r$ given that $\min\{j_t-i_t \mid t=1,\ldots,s\}\ge 2$ and $i_b\le i_h$, and an integer $n\ge 2r$. \\
\textbf{Output}: A sequence of numbers $a_1,\ldots,a_d,a_{d+1} \in \{1,2,\ldots,n+r\}$.
\end{flushleft}
	\begin{algorithmic} 
		\State{$\epsilon:= \max\{t \in {\mathbb Z}_{\ge 0} \mid t(j_{u_{\beta}} - i_{u_{\beta}}-1) + i_{u_{\beta}}< i_{b}\}$}
		\State{$a_1:=\epsilon(j_{u_{\beta}} - i_{u_{\beta}}-1) + i_{u_{\beta}}$}
		\State{${\rm term}:=a_1$}
		\State{$d:=1$}
		\While{${\rm term} < i_h$}
		\State{$t=\min\{\alpha\in\{1,\ldots,\beta\} \mid i_{u_\alpha}\le {\rm term}\}$}
		\State{${\rm term}:={\rm term}+ j_{u_t} -i_{u_t} -1$}
		\State{$a_{d+1}:={\rm term}$}
		\State{$d:=d+1$}
		\EndWhile
	\end{algorithmic}
\end{algorithm}
Note that
\begin{equation}
\label{eq_a2-a1}
a_2=a_1+j_{u_\beta} -i_{u_\beta} -1.
\end{equation}
Indeed, by \Cref{constr_Jsets}, $i_{u_\beta} < i_b \le i_{u_{\beta-1}}$, so $a_1=\epsilon(j_{u_{\beta}} - i_{u_{\beta}}-1) + i_{u_{\beta}} <i_b \le i_{u_{\beta-1}}$. Hence at the step $d=1$, 
\[
t=\min\{\alpha\in\{1,\ldots,\beta\} \mid i_{u_\alpha}\le a_1\}=\beta.
\]
From this, \eqref{eq_a2-a1} follows.



At the end of  Algorithm~\ref{alg:anticycle_initialvertices}, we get a sequence $a_1,\ldots,a_{d+1}$ satisfying 
\[
i_q\le i_{u_{\beta}}\leq a_1<i_b\le a_2<a_3<\cdots<a_d< i_h\le a_{d+1}=a_d+j_{u_t}-i_{u_t}-1,
\] 
where $t=\min\{\alpha\in\{1,\ldots,\beta\} \mid i_{u_\alpha}\le a_d\}$.

At this point, note that $v_\gamma=B$ per \eqref{eq_vgammaB}, so
\[
a_{d+1}=a_d+j_{u_t}-i_{u_t}-1 < i_h+j_{u_t}-i_{u_t}-1 < 2r < n+i_{v_\gamma} = n +i_B,
\]
using the hypothesis on $n$. Thus we may apply Algorithm~\ref{alg:anticycle_finalvertices} with $a_\textsf{index}:=a_{d+1}$. Note that the numbers $\gamma, H=v_1, v_2,\ldots,v_{\gamma}=B$ in \Cref{alg:anticycle_finalvertices} come from the output of \Cref{alg_Ksets}.

\begin{algorithm}[H]
	\caption{Generate the final vertices of an induced anticycle in $G_{n+r}$}
	\label{alg:anticycle_finalvertices}
	\begin{flushleft}
\textbf{Input}: The set of edges $\{\{i_1,j_1\},\ldots,\{i_s,j_s\}\}$ of $G_r$ and integers $n\ge 2r$ and $i_h \le a_\textsf{index} \le n+r$.  \\
\textbf{Output}: A sequence of numbers $a_\textsf{index},a_{\textsf{index}+1}\ldots,a_m \in \{1,2,\ldots,n+r\}$.
	\end{flushleft}
	\begin{algorithmic}
		\State{${\rm term}:= a_{\textsf{index}}$}
		\State{$\nu:=1$}
		\While{${\rm term}\le n+i_B$}
		\State{$t=\min\{\alpha\in\{1,\ldots,\gamma\} \mid {\rm term} \le n+i_{v_\alpha}\}$}
		\State{${\rm term}:= {\rm term}+j_{v_{t}} - i_{v_{t}}-1$}
		\State{$a_{\textsf{index}+\nu}:={\rm term}$}
		\State{$\nu:=\nu+1$}
		\EndWhile
		\State{$m:=\nu+1$}
		\State{$a_{m}:=n+j_B$}
	\end{algorithmic}
\end{algorithm}

\label{thm_convergence}
Let ${\mathcal I}=(I_n)_{n\ge 1}$ be an $\operatorname{Inc}$-invariant chain of eventually nonzero edge ideals. Keep using \Cref{notn_chainofedgeids}. Then for all $n\ge N=\max\{5r, 2r(r-2), 4(r+q(I_r))\}$, there is an equality
\[
\operatorname{reg} I_n = \operatorname{reg} I_{n+1},
\]
and moreover $\lim\limits_{n\to \infty} \operatorname{reg} I_n \in \{2,3\}$.

In addition, the following statements are equivalent
\begin{enumerate}[\quad \rm (1)]
 \item $\operatorname{reg} I_n=2$ for all $n\gg 0$;
 \item $\operatorname{reg} I_N=2$;
 \item  Either $j_q = \max\{j_1,\ldots,j_s\}$, or it holds that $\min \{j_t-i_t: t=1,\ldots,s\}=1$ and $\operatorname{indmatch}(G_{3r})=1$.
\end{enumerate}
